import { StorybookConfig } from "@storybook/react-vite";
import { mergeConfig } from "vite";
import svgr from "vite-plugin-svgr";
import remarkGfm from "remark-gfm";

/**
 * react docgen propFilter function
 * @see https://github.com/styleguidist/react-docgen-typescript#propfilter
 */
const propFilterFn = (prop, component) => {
  const hasDesc = prop.description.length > 0;
  const hasParent = prop.parent !== undefined;
  // filter out props without descriptions
  if (!hasDesc) return false;
  // always include props of components without parents
  if (!hasParent) return true;
  // only include props from src/components and utilities
  const parentFileName = prop.parent.fileName;
  return parentFileName.includes("src/components");
};

// see https://storybook.js.org/docs/configurations/typescript-config/
// see https://github.com/storybookjs/storybook/blob/next/docs/src/pages/configurations/typescript-config/index.md#mainjs-configuration
const config: StorybookConfig = {
  staticDirs: ["../public"],
  framework: {
    name: "@storybook/react-vite",
    options: {},
  },
  stories: [
    "../src/doc/*.@(mdx|stories.@(jsx|tsx))",
    "../src/**/*.doc.mdx",
    "../src/components/**/*.stories.tsx",
  ],
  typescript: {
    check: false,
    // https://storybook.js.org/docs/api/main-config/main-config-typescript#reactdocgen
    reactDocgen: "react-docgen-typescript", // "react-docgen", false
    reactDocgenTypescriptOptions: {
      propFilter: propFilterFn,
      shouldExtractLiteralValuesFromEnum: true,
      compilerOptions: {
        allowSyntheticDefaultImports: false,
        esModuleInterop: false,
      },
    },
  },

  core: {
    disableTelemetry: true, // 👈 Disables telemetry
    builder: "@storybook/builder-vite", // 👈 The builder enabled here.

    // options: {
    //   lazyCompilation: true,
    //   fsCache: true,
    // }
  },
  addons: [
    "@storybook/addon-links",
    "@storybook/addon-a11y",
    "@storybook/addon-themes",
    {
      name: "@storybook/addon-essentials", //disable docs, since it is handled below cos of remarkgfm
      options: {
        docs: false,
      },
    },
    "@airbus/storybook-addon-posthog",
    {
      name: "@storybook/addon-docs",
      options: {
        mdxPluginOptions: {
          mdxCompileOptions: {
            remarkPlugins: [remarkGfm], // adding to support md files. example in migration file
          },
        },
      },
    },
  ],
  docs: {
    autodocs: true, //to consistently render docs page without intermittent issue
  },
  viteFinal: async (config) => {
    return mergeConfig(config, {
      plugins: [svgr()],
      // https://github.com/storybookjs/storybook/issues/22223
      build: {
        target: 'esnext'
      },
    });
  },
};

export default config;
